# Restore the two omitted transcription endings from their clear repeating rows.
for i in (20,25): grid[i].append(5)
P=[1,3,5,7,9]
pos={v:i for i,v in enumerate(P)}
out=[row[:] for row in grid]
for r in range(28):
 for c in range(28):
  if out[r][c]!=0: continue
  if r<2 or c<2:
   out[r][c]=1
  elif r==2 or c==2:
   out[r][c]=4
  else:
   known=[k for k in range(3,28) if grid[r][k] in pos]
   assert known, r
   k=min(known,key=lambda k:abs(k-c))
   out[r][c]=P[(pos[grid[r][k]]+c-k)%5]
print('\n'.join(' '.join(map(str,row)) for row in out))
